"""Use the development plugin ID generated by your own Figma account.

Run inside the extracted Wilco bundle:
  python3 configure.py --from-manifest /path/to/figma-generated/manifest.json
Then import this bundle's manifest.json in Figma desktop.
"""
import argparse
import json
import re
from pathlib import Path

parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument('--from-manifest', type=Path, required=True)
args = parser.parse_args()
root = Path(__file__).resolve().parent
try:
    source = json.loads(args.from_manifest.read_text())
    identifier = source.get('id', '')
    if not isinstance(identifier, str) or not re.fullmatch(r'[0-9]{6,30}', identifier):
        parser.error('Use the manifest generated by Figma when you create a new development plugin.')
    path = root/'manifest.json'
    manifest = json.loads(path.read_text())
    manifest['id'] = identifier
    path.write_text(json.dumps(manifest, indent=2)+'\n')
except (OSError, ValueError) as error:
    parser.error('Could not read those plugin files. Check both manifest paths.')
print('Ready to import:', path)
